from functools import lru_cache
n=15
N=2*n
fixed={3:2,11:14,13:11,26:14,27:7,28:10}
# possible placements per v (list tuple positions)
placements={}
for v in range(1,n+1):
    d=v+1
    opts=[]
    for i in range(N-d):
        p=(i,i+d)
        ok=True
        # if any pos fixed to other value -> invalid
        for pos,val in fixed.items():
            if pos in p:
                if val!=v: ok=False
            else:
                if val==v:
                    # fixed occurrence of v not included -> invalid? Since placement for v must include all fixed pos with val v
                    pass
        # require include all fixed positions where val==v
        if ok and all(pos in p for pos,val in fixed.items() if val==v):
            opts.append(p)
    placements[v]=opts
    print(v,len(opts),opts[:10])

# backtracking choose value with fewest opts considering occupied
seq=[0]*N
occupied=0
# mark? no positions not preoccupied unless choosing placements, fixed is only constraints.
values=set(range(1,n+1))

def backtrack(unassigned, occupied):
    if not unassigned:
        return []
    # select v with fewest available placements disjoint from occupied
    best=None; bestopts=None
    for v in unassigned:
        opts=[p for p in placements[v] if not ((1<<p[0])| (1<<p[1])) & occupied]
        if best is None or len(opts)<len(bestopts):
            best=v; bestopts=opts
        if len(opts)==0: return None
    # maybe sort descending constraints
    for p in bestopts:
        res=backtrack(unassigned-{best}, occupied | (1<<p[0]) | (1<<p[1]))
        if res is not None:
            return [(best,p)] + res
    return None
res=backtrack(frozenset(values),0)
print(res)
if res:
    seq=[0]*N
    for v,p in res:
        seq[p[0]]=seq[p[1]]=v
    print(seq)
    print({i:seq[i] for i in fixed}, fixed)
    # verify
    for v in range(1,n+1):
